","/* ═══════════════════════════════════════════════════════════════════
 DarkOps — Premium Enterprise Homepage
 Design: Microsoft Security Center / Datadog / Linear quality
 ═══════════════════════════════════════════════════════════════════ */

/* ─── Reset ───────────────────────────────────────────────────────── */
*,
*::before,
*::after {
 box-sizing: border-box;
 margin: 0;
 padding: 0;
}

html, body {
 margin: 0 !important;
 padding: 0 !important;
 background: #0a0e14 !important;
 font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
 -webkit-font-smoothing: antialiased;
 -moz-osx-font-smoothing: grayscale;
 overflow: hidden;
}

a {
 text-decoration: none;
 color: inherit;
}

/* ─── App Shell ───────────────────────────────────────────────────── */
.darkops-home {
 height: 100vh;
 width: 100vw;
 display: flex;
 flex-direction: column;
 background: #0a0e14;
 color: #e2e8f0;
 overflow-y: auto;
 overflow-x: hidden;
 position: relative;
}

.darkops-home::before {
 content: "";
 position: fixed;
 top: 0;
 left: 0;
 right: 0;
 height: 600px;
 background: radial-gradient(ellipse 80% 50% at 50% -20%, rgba(139, 92, 246, 0.12), transparent),
 radial-gradient(ellipse 60% 40% at 80% 0%, rgba(6, 182, 212, 0.06), transparent),
 radial-gradient(ellipse 40% 30% at 20% 10%, rgba(99, 102, 241, 0.05), transparent);
 pointer-events: none;
 z-index: 0;
}

.darkops-main {
 flex: 1;
 max-width: 1200px;
 width: 100%;
 margin: 0 auto;
 padding: 0 32px 64px;
 position: relative;
 z-index: 1;
}

/* ─── Section Headers ─────────────────────────────────────────────── */
.section-header {
 margin-bottom: 20px;
 display: flex;
 align-items: center;
 gap: 10px;
}

.section-title {
 font-size: 1.15rem;
 font-weight: 600;
 color: #f1f5f9;
 letter-spacing: -0.01em;
}

/* ═══════════════════════════════════════════════════════════════════
 HERO SECTION
 ═══════════════════════════════════════════════════════════════════ */
.hero {
 padding: 48px 32px 36px;
 text-align: center;
 position: relative;
 z-index: 1;
}

.hero__content {
 max-width: 680px;
 margin: 0 auto;
}

.hero__logo-wrap {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 width: 64px;
 height: 64px;
 border-radius: 16px;
 background: linear-gradient(135deg, #8b5cf6, #6366f1);
 margin-bottom: 18px;
 box-shadow: 0 4px 24px rgba(139, 92, 246, 0.35),
 0 0 60px rgba(139, 92, 246, 0.12);
 animation: heroLogoFloat 3s ease-in-out infinite;
 position: relative;
}

.hero__logo-wrap::after {
 content: "";
 position: absolute;
 inset: -2px;
 border-radius: 18px;
 background: linear-gradient(135deg, rgba(139, 92, 246, 0.4), rgba(99, 102, 241, 0.2));
 z-index: -1;
 filter: blur(8px);
 opacity: 0.6;
}

@keyframes heroLogoFloat {
 0%, 100% { transform: translateY(0); }
 50% { transform: translateY(-4px); }
}

.hero__logo {
 font-size: 26px;
 line-height: 1;
 display: flex;
 align-items: center;
 justify-content: center;
}

.hero__title {
 font-size: 2.8rem;
 font-weight: 800;
 letter-spacing: -0.04em;
 background: linear-gradient(135deg, #ffffff 0%, #e2e8f0 40%, #8b5cf6 100%);
 -webkit-background-clip: text;
 -webkit-text-fill-color: transparent;
 background-clip: text;
 margin-bottom: 4px;
 line-height: 1.1;
}

.hero__tagline {
 font-size: 1rem;
 color: #94a3b8;
 font-weight: 400;
 margin-bottom: 4px;
 letter-spacing: 0.01em;
}

.hero__desc {
 font-size: 0.85rem;
 color: #64748b;
 margin-bottom: 16px;
}

.hero__greeting {
 font-size: 0.85rem;
 color: #64748b;
 margin-bottom: 24px;
}

.hero__greeting strong {
 color: #cbd5e1;
 font-weight: 600;
}

/* ─── CTA Card ────────────────────────────────────────────────────── */
.hero__cta {
 display: inline-flex;
 align-items: center;
 gap: 14px;
 padding: 16px 32px;
 background: #111621;
 border: 1px solid #2d1b69;
 border-radius: 12px;
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 position: relative;
 overflow: hidden;
}

.hero__cta::before {
 content: "";
 position: absolute;
 inset: 0;
 background: linear-gradient(135deg, rgba(139, 92, 246, 0.08), rgba(99, 102, 241, 0.04));
 transition: background 0.3s ease;
}

.hero__cta:hover {
 transform: translateY(-2px);
 border-color: #8b5cf6;
 box-shadow: 0 0 30px rgba(139, 92, 246, 0.2), 0 4px 20px rgba(0, 0, 0, 0.4);
}

.hero__cta:hover::before {
 background: linear-gradient(135deg, rgba(139, 92, 246, 0.14), rgba(99, 102, 241, 0.08));
}

.hero__cta-icon {
 position: relative;
 z-index: 1;
 display: flex;
 align-items: center;
 justify-content: center;
 transition: transform 0.3s ease;
}

.hero__cta:hover .hero__cta-icon {
 transform: scale(1.1);
}

.hero__cta-content {
 text-align: left;
 position: relative;
 z-index: 1;
}

.hero__cta-title {
 font-size: 0.95rem;
 font-weight: 600;
 color: #f1f5f9;
}

.hero__cta-sub {
 font-size: 0.78rem;
 color: #64748b;
 margin-top: 2px;
}

.hero__cta-arrow {
 color: #8b5cf6;
 position: relative;
 z-index: 1;
 transition: transform 0.3s ease;
 display: flex;
 align-items: center;
}

.hero__cta:hover .hero__cta-arrow {
 transform: translateX(4px);
}

/* ═══════════════════════════════════════════════════════════════════
 COMMAND CENTERS
 ═══════════════════════════════════════════════════════════════════ */
.command-section {
 margin-bottom: 48px;
}

.nav-grid {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 16px;
}

.nav-card {
 display: flex;
 flex-direction: column;
 padding: 24px;
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 cursor: pointer;
 position: relative;
 overflow: hidden;
}

.nav-card::after {
 content: "";
 position: absolute;
 top: 0;
 left: 0;
 right: 0;
 height: 2px;
 background: linear-gradient(90deg, transparent, rgba(139, 92, 246, 0.6), transparent);
 opacity: 0;
 transition: opacity 0.3s ease;
}

.nav-card:hover {
 transform: translateY(-4px);
 border-color: #2a3555;
 box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), 0 0 20px rgba(139, 92, 246, 0.06);
 background: #151d2e;
}

.nav-card:hover::after {
 opacity: 1;
}

.nav-card__icon {
 width: 40px;
 height: 40px;
 display: flex;
 align-items: center;
 justify-content: center;
 border-radius: 10px;
 background: #151d2e;
 margin-bottom: 16px;
 transition: all 0.3s ease;
}

.nav-card:hover .nav-card__icon {
 background: rgba(139, 92, 246, 0.12);
 transform: scale(1.05);
}

.nav-card__icon svg {
 transition: transform 0.3s ease;
}

.nav-card:hover .nav-card__icon svg {
 transform: scale(1.1);
}

.nav-card__title {
 font-size: 0.92rem;
 font-weight: 600;
 color: #f1f5f9;
 margin-bottom: 8px;
}

.nav-card__desc {
 font-size: 0.8rem;
 color: #64748b;
 line-height: 1.5;
 flex: 1;
 margin-bottom: 16px;
}

.nav-card__link {
 font-size: 0.78rem;
 font-weight: 500;
 color: #8b5cf6;
 display: flex;
 align-items: center;
 gap: 6px;
 transition: gap 0.2s ease;
}

.nav-card:hover .nav-card__link {
 gap: 10px;
}

.nav-card__arrow-svg {
 transition: transform 0.2s ease;
}

.nav-card:hover .nav-card__arrow-svg {
 transform: translateX(2px);
}

/* ═══════════════════════════════════════════════════════════════════
 OPERATIONAL SNAPSHOT
 ═══════════════════════════════════════════════════════════════════ */
.snapshot-section {
 margin-bottom: 48px;
}

.kpi-grid {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 16px;
}

.kpi-card {
 padding: 20px 24px;
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 display: flex;
 flex-direction: column;
 gap: 4px;
 transition: all 0.25s ease;
 position: relative;
 overflow: hidden;
}

.kpi-card::before {
 content: "";
 position: absolute;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 opacity: 0;
 transition: opacity 0.3s ease;
 pointer-events: none;
}

.kpi-card--critical::before {
 background: radial-gradient(ellipse at bottom left, rgba(239, 68, 68, 0.04), transparent 70%);
}

.kpi-card--warning::before {
 background: radial-gradient(ellipse at bottom left, rgba(245, 158, 11, 0.04), transparent 70%);
}

.kpi-card--info::before {
 background: radial-gradient(ellipse at bottom left, rgba(59, 130, 246, 0.04), transparent 70%);
}

.kpi-card--alert::before {
 background: radial-gradient(ellipse at bottom left, rgba(6, 182, 212, 0.04), transparent 70%);
}

.kpi-card:hover {
 border-color: #2a3555;
 background: #151d2e;
}

.kpi-card:hover::before {
 opacity: 1;
}

.kpi-card--critical {
 border-left: 3px solid #ef4444;
}

.kpi-card--warning {
 border-left: 3px solid #f59e0b;
}

.kpi-card--info {
 border-left: 3px solid #3b82f6;
}

.kpi-card--alert {
 border-left: 3px solid #06b6d4;
}

.kpi-card__header {
 display: flex;
 align-items: center;
 gap: 8px;
 margin-bottom: 8px;
}

.kpi-card__dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 display: inline-block;
 position: relative;
 flex-shrink: 0;
}

.kpi-card__dot::after {
 content: "";
 position: absolute;
 inset: -2px;
 border-radius: 50%;
 background: inherit;
 opacity: 0.3;
 animation: kpiPulse 2s ease-in-out infinite;
}

@keyframes kpiPulse {
 0%, 100% { transform: scale(1); opacity: 0.3; }
 50% { transform: scale(1.6); opacity: 0; }
}

.kpi-card__icon {
 font-size: 0.95rem;
 line-height: 1;
}

.kpi-card__label {
 font-size: 0.72rem;
 font-weight: 600;
 color: #64748b;
 text-transform: uppercase;
 letter-spacing: 0.05em;
}

.kpi-card__value {
 font-size: 1.8rem;
 font-weight: 700;
 color: #f1f5f9;
 letter-spacing: -0.02em;
 line-height: 1.2;
 font-variant-numeric: tabular-nums;
}

.kpi-card__sub {
 font-size: 0.75rem;
 color: #64748b;
}

/* ═══════════════════════════════════════════════════════════════════
 QUICK ACTIONS
 ═══════════════════════════════════════════════════════════════════ */
.actions-section {
 margin-bottom: 48px;
}

.actions-grid {
 display: grid;
 grid-template-columns: repeat(3, 1fr);
 gap: 12px;
}

.action-card {
 display: flex;
 align-items: center;
 gap: 14px;
 padding: 16px 20px;
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 10px;
 transition: all 0.25s ease;
 cursor: pointer;
}

.action-card:hover {
 background: #151d2e;
 border-color: #2a3555;
 transform: translateY(-2px);
 box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.action-card__icon {
 display: flex;
 align-items: center;
 justify-content: center;
 width: 36px;
 height: 36px;
 border-radius: 8px;
 background: rgba(139, 92, 246, 0.08);
 border: 1px solid rgba(139, 92, 246, 0.15);
 flex-shrink: 0;
 transition: all 0.25s ease;
}

.action-card:hover .action-card__icon {
 background: rgba(139, 92, 246, 0.14);
 border-color: rgba(139, 92, 246, 0.3);
 transform: scale(1.05);
}

.action-card__label {
 font-size: 0.87rem;
 font-weight: 500;
 color: #f1f5f9;
}

.action-card__arrow {
 margin-left: auto;
 color: #64748b;
 transition: transform 0.2s ease, color 0.2s ease;
 display: flex;
 align-items: center;
}

.action-card:hover .action-card__arrow {
 transform: translateX(3px);
 color: #8b5cf6;
}

/* ═══════════════════════════════════════════════════════════════════
 FOOTER
 ═══════════════════════════════════════════════════════════════════ */
.darkops-footer {
 padding: 24px 32px;
 text-align: center;
 border-top: 1px solid #1a2035;
}

.darkops-footer__text {
 font-size: 0.75rem;
 color: #475569;
 letter-spacing: 0.02em;
}

/* ═══════════════════════════════════════════════════════════════════
 RESPONSIVE
 ═══════════════════════════════════════════════════════════════════ */
@media (max-width: 1024px) {
 .nav-grid {
 grid-template-columns: repeat(2, 1fr);
 }
 .kpi-grid {
 grid-template-columns: repeat(2, 1fr);
 }
}

@media (max-width: 768px) {
 .hero {
 padding: 40px 20px 32px;
 }
 .hero__title {
 font-size: 2rem;
 }
 .darkops-main {
 padding: 0 20px 48px;
 }
 .nav-grid {
 grid-template-columns: 1fr;
 }
 .kpi-grid {
 grid-template-columns: 1fr 1fr;
 }
 .actions-grid {
 grid-template-columns: 1fr;
 }
}

@media (max-width: 480px) {
 .kpi-grid {
 grid-template-columns: 1fr;
 }
 .hero__cta {
 padding: 14px 20px;
 gap: 10px;
 }
}

/* ─── Animations ──────────────────────────────────────────────────── */
@keyframes fadeInUp {
 from {
 opacity: 0;
 transform: translateY(16px);
 }
 to {
 opacity: 1;
 transform: translateY(0);
 }
}

.hero {
 animation: fadeInUp 0.6s ease forwards;
}

.command-section {
 animation: fadeInUp 0.6s ease 0.1s forwards;
 opacity: 0;
}

.snapshot-section {
 animation: fadeInUp 0.6s ease 0.2s forwards;
 opacity: 0;
}

.actions-section {
 animation: fadeInUp 0.6s ease 0.3s forwards;
 opacity: 0;
}

/* ─── Scrollbar ───────────────────────────────────────────────────── */
.darkops-home::-webkit-scrollbar {
 width: 6px;
}

.darkops-home::-webkit-scrollbar-track {
 background: transparent;
}

.darkops-home::-webkit-scrollbar-thumb {
 background: #1e293b;
 border-radius: 3px;
}

.darkops-home::-webkit-scrollbar-thumb:hover {
 background: #334155;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect, useRef } from "react";

interface KpiMetric {
 label: string;
 value: string;
 numericValue: number;
 prefix: string;
 suffix: string;
 subtitle: string;
 severity: "critical" | "warning" | "info" | "alert";
}

const METRICS: KpiMetric[] = [
 { label: "Critical Stores", value: "3", numericValue: 3, prefix: "", suffix: "", subtitle: "Needs Attention", severity: "critical" },
 { label: "Open Complaints", value: "47", numericValue: 47, prefix: "", suffix: "", subtitle: "Active cases", severity: "warning" },
 { label: "Today's Refunds", value: "₹1.84L", numericValue: 1.84, prefix: "₹", suffix: "L", subtitle: "296 processed", severity: "info" },
 { label: "Fraud Alerts", value: "7", numericValue: 7, prefix: "", suffix: "", subtitle: "2 high confidence", severity: "alert" },
];

const SEVERITY_COLORS: Record<string, string> = {
 critical: "#ef4444",
 warning: "#f59e0b",
 info: "#3b82f6",
 alert: "#06b6d4",
};

/* Animated counter hook */
function useAnimatedCounter(target: number, duration: number = 1200, decimals: number = 0): number {
 const [current, setCurrent] = useState(0);
 const frameRef = useRef<number>(0);
 const startTimeRef = useRef<number>(0);

 useEffect(() => {
 startTimeRef.current = performance.now();

 function animate(now: number) {
 const elapsed = now - startTimeRef.current;
 const progress = Math.min(elapsed / duration, 1);
 /* Ease-out cubic for smooth deceleration */
 const eased = 1 - Math.pow(1 - progress, 3);
 const val = eased * target;
 setCurrent(val);
 if (progress < 1) {
 frameRef.current = requestAnimationFrame(animate);
 } else {
 setCurrent(target);
 }
 }

 frameRef.current = requestAnimationFrame(animate);
 return () => cancelAnimationFrame(frameRef.current);
 }, [target, duration]);

 return decimals > 0 ? parseFloat(current.toFixed(decimals)) : Math.round(current);
}

interface KpiCardProps { metric: KpiMetric; delay: number; key?: string; }

/* Individual KPI card with animated value */
function KpiCard({ metric, delay }: KpiCardProps) {
 const [visible, setVisible] = useState(false);
 const decimals = metric.suffix === "L" ? 2 : 0;
 const animatedValue = useAnimatedCounter(
 visible ? metric.numericValue : 0,
 1400,
 decimals
 );

 useEffect(() => {
 const timer = setTimeout(() => setVisible(true), delay);
 return () => clearTimeout(timer);
 }, [delay]);

 const displayValue = visible
 ? `${metric.prefix}${decimals > 0 ? animatedValue.toFixed(decimals) : animatedValue}${metric.suffix}`
 : `${metric.prefix}0${metric.suffix}`;

 const dotColor = SEVERITY_COLORS[metric.severity];

 return (
 <div className={`kpi-card kpi-card--${metric.severity}`}>
 <div className="kpi-card__header">
 <span className="kpi-card__dot" style={{ backgroundColor: dotColor }} />
 <span className="kpi-card__label">{metric.label}</span>
 </div>
 <span className="kpi-card__value">{displayValue}</span>
 <span className="kpi-card__sub">{metric.subtitle}</span>
 </div>
 );
}

export default function KpiCards() {
 return (
 <section className="snapshot-section">
 <div className="section-header">
 <h2 className="section-title">Operational Snapshot</h2>
 </div>
 <div className="kpi-grid">
 {METRICS.map((metric, i) => (
 <KpiCard key={metric.label} metric={metric} delay={300 + i * 150} />
 ))}
 </div>
 </section>
 );
}
","import React, { useState, useEffect } from "react";
import "./home.css";
import HeroHeader from "./components/HeroHeader";
import NavCards from "./components/NavCards";
import KpiCards from "./components/KpiCards";

const WIN = window as any;

interface QuickAction {
 icon: React.ReactNode;
 label: string;
 url: string;
}

/* SVG icons for quick actions */
function CopilotSmallIcon() {
 return (
 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
 <path d="M12 2L20 6.5V17.5L12 22L4 17.5V6.5L12 2Z" stroke="#a78bfa" strokeWidth="1.5" fill="none" />
 <circle cx="12" cy="12" r="3" fill="#a78bfa" opacity="0.7" />
 <line x1="12" y1="9" x2="12" y2="5.5" stroke="#a78bfa" strokeWidth="1" opacity="0.6" />
 <line x1="12" y1="15" x2="12" y2="18.5" stroke="#a78bfa" strokeWidth="1" opacity="0.6" />
 </svg>
 );
}

function GlobeIcon() {
 return (
 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
 <circle cx="12" cy="12" r="9.5" stroke="#8b5cf6" strokeWidth="1.5" />
 <ellipse cx="12" cy="12" rx="4" ry="9.5" stroke="#8b5cf6" strokeWidth="1.2" />
 <path d="M3.5 9H20.5" stroke="#8b5cf6" strokeWidth="1" opacity="0.6" />
 <path d="M3.5 15H20.5" stroke="#8b5cf6" strokeWidth="1" opacity="0.6" />
 </svg>
 );
}

function DashboardIcon() {
 return (
 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
 <rect x="3" y="3" width="8" height="8" rx="2" stroke="#8b5cf6" strokeWidth="1.5" />
 <rect x="13" y="3" width="8" height="4" rx="1.5" stroke="#8b5cf6" strokeWidth="1.5" />
 <rect x="13" y="9" width="8" height="12" rx="2" stroke="#8b5cf6" strokeWidth="1.5" />
 <rect x="3" y="13" width="8" height="8" rx="2" stroke="#8b5cf6" strokeWidth="1.5" />
 </svg>
 );
}

/* Arrow icon */
function ArrowSmallIcon() {
 return (
 <svg width="14" height="14" viewBox="0 0 14 14" fill="none" xmlns="http://www.w3.org/2000/svg">
 <path d="M3 7H11M11 7L7.5 3.5M11 7L7.5 10.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
 </svg>
 );
}

const QUICK_ACTIONS: QuickAction[] = [
 { icon: <CopilotSmallIcon />, label: "Open AI Copilot", url: "x_2145749_qc_copilot.do" },
 { icon: <GlobeIcon />, label: "Customer Portal", url: "x_2145749_qc_assistant.do" },
 { icon: <DashboardIcon />, label: "Operations Dashboard", url: "x_2145749_qc_ops_dashboard.do" },
];

function fetchUserName(cb: (name: string) => void) {
 const userName = WIN.NOW?.user?.name || "";
 if (!userName) { cb("Operator"); return; }
 fetch(
 `/api/now/table/sys_user?sysparm_query=user_name=${userName}&sysparm_fields=first_name&sysparm_limit=1`,
 { headers: { "X-UserToken": WIN.g_ck, Accept: "application/json" } }
 )
 .then((r) => r.json())
 .then((d) => { cb(d?.result?.[0]?.first_name || "Operator"); })
 .catch(() => cb("Operator"));
}

export default function App() {
 const [userName, setUserName] = useState("...");
 useEffect(() => { fetchUserName(setUserName); }, []);

 return (
 <div className="darkops-home">
 <HeroHeader userName={userName} />
 <main className="darkops-main">
 <NavCards />
 <KpiCards />
 <section className="actions-section">
 <div className="section-header">
 <h2 className="section-title">Quick Actions</h2>
 </div>
 <div className="actions-grid">
 {QUICK_ACTIONS.map((action) => (
 <a className="action-card" key={action.label} href={action.url}>
 <span className="action-card__icon">{action.icon}</span>
 <span className="action-card__label">{action.label}</span>
 <span className="action-card__arrow"><ArrowSmallIcon /></span>
 </a>
 ))}
 </div>
 </section>
 </main>
 <footer className="darkops-footer">
 <p className="darkops-footer__text">DarkOps v1.0 • AI-Powered Operations Intelligence</p>
 </footer>
 </div>
 );
}
